def transform(grid):
    import numpy as np
    g=[row[:] for row in grid]
    a=np.array(grid)
    rows=[i for i in range(a.shape[0]) if (a[i]==8).any()]
    # split into contiguous clusters
    groups=[]; cur=[rows[0]]
    for r in rows[1:]:
        if r==cur[-1]+1: cur.append(r)
        else: groups.append(cur); cur=[r]
    groups.append(cur)
    def fg(rws):
        m=np.zeros_like(a,dtype=bool)
        for r in rws: m[r]=(a[r]==8)
        return m
    if len(groups)==2:
        c1,c2=fg(groups[0]),fg(groups[1])
        # find best dx maximizing c2(i,j)->c1(i,j+dx) matches
        best=(1e9,0)
        for dx in range(-13,14):
            miss=0
            for i in range(a.shape[0]):
                for j in range(a.shape[1]):
                    if c2[i,j] and (j+dx<0 or j+dx>=a.shape[1] or not c1[i,j+dx]): miss+=1
            if miss<best[0]: best=(miss,dx)
        miss,dx=best
        if miss==0:
            # c2 subset of c1 (shifted): c2 is deficient -> fill c2 cells where c1 has fg it lacks
            for i in range(a.shape[0]):
                for j in range(a.shape[1]):
                    if 0<=j-dx<a.shape[1] and c1[i,j-dx] and not c2[i,j] and (c2[i].any() if True else True):
                        g[i][j]=1
    return g

